// Bounded event queue + ten-second metric buckets. No DOM dependencies.
export const freshStats=time=>({since:time,buckets:[],sentenceChars:0,sentenceWords:0,sentenceSamples:0,bestLetterRate:0,milestones:{},estimated:false});
export function emit(s,type,payload={}){s.events.push({type,time:s.time,...payload});if(s.events.length>32)s.events.shift()}
const milestones={DUST_PRODUCED:'firstDust',LETTER_PRODUCED:'firstLetter',WORD_PRODUCED:'firstWord',VALID_WORD_PRODUCED:'firstValidWord',SENTENCE_PRODUCED:'firstSentence'};
const totals={DUST_PRODUCED:'dust',LETTER_PRODUCED:'letters',WORD_PRODUCED:'words',VALID_WORD_PRODUCED:'validWords',SENTENCE_PRODUCED:'sentences'};
export function observe(s,type,payload={},count=1){s.stats??=freshStats(s.time);const stats=s.stats,key=totals[type];if(key){const bin=Math.floor(s.time/10)*10;let b=stats.buckets.at(-1);if(!b||b.at!==bin){b={at:bin,dust:0,letters:0,words:0,validWords:0,sentences:0,letterSupply:{}};stats.buckets.push(b);if(stats.buckets.length>361)stats.buckets.splice(0,stats.buckets.length-361)}b[key]+=count;if(type==='LETTER_PRODUCED'&&payload.text)b.letterSupply[payload.text]=(b.letterSupply[payload.text]||0)+count;const stamp=milestones[type];if(stats.milestones[stamp]===undefined&&s.counts[key]===count){stats.milestones[stamp]={seconds:s.time,estimated:!!s.offlineBatch};emit(s,type,{title:{DUST_PRODUCED:'Première étincelle',LETTER_PRODUCED:'Première lettre',WORD_PRODUCED:'Premier mot',VALID_WORD_PRODUCED:'Un vrai mot !',SENTENCE_PRODUCED:'L’usine sait écrire'}[type],text:payload.text||'Votre première poussière est extraite.'})}}
 if(type==='SENTENCE_PRODUCED'){stats.sentenceSamples+=count;stats.sentenceChars+=(payload.chars||0)*count;stats.sentenceWords+=(payload.words||0)*count}
}
export function statistics(s){const st=s.stats||freshStats(s.time),minute=st.buckets.filter(b=>b.at>s.time-60),hour=st.buckets.filter(b=>b.at>s.time-3600),minSpan=Math.max(1,Math.min(60,s.time-st.since)),hourSpan=Math.max(1,Math.min(3600,s.time-st.since));const sum=(list,k)=>list.reduce((n,b)=>n+(b[k]||0),0),supply={};for(const b of minute)for(const[c,n]of Object.entries(b.letterSupply||{}))supply[c]=(supply[c]||0)+n*60/minSpan;const letters=sum(minute,'letters')*60/minSpan;return{letters,words:sum(minute,'words')*60/minSpan,validWords:sum(minute,'validWords')*60/minSpan,sentences:sum(hour,'sentences')*3600/hourSpan,average:st.sentenceSamples?st.sentenceChars/st.sentenceSamples:null,efficiency:s.machines.reduce((n,m)=>n+m.age,0)?100*s.machines.reduce((n,m)=>n+m.work,0)/s.machines.reduce((n,m)=>n+m.age,0):0,supply,window:minSpan,hourWindow:hourSpan,estimated:st.estimated}}
